// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // Expectation: P.getPrice returns 0 for all inputs
        // M returns block.timestamp, which is never 0 in a running chain
        // We call assertionDisputedCallback to trigger the getPrice call
        // But getPrice is view, so we can call it directly
        int256 result = c.getPrice(identifier, time, ancillaryData);
        assertTrue(result == 0, "getPrice should return 0");
    }
}

